class Solution(object):
    def shortestCommonSupersequence(self, str1, str2):
        """
        :type str1: str
        :type str2: str
        :rtype: str
        """
        n, m = len(str1), len(str2)
        dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
        for i in range(n):
            dp[i][m] = n - i
        for j in range(m):
            dp[n][j] = m - j
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                if str1[i] == str2[j]:
                    dp[i][j] = dp[i + 1][j + 1] + 1
                else:
                    dp[i][j] = min(dp[i + 1][j], dp[i][j + 1]) + 1
        ans = ""
        p1 = p2 = 0
        while p1 < n and p2 < m:
            if str1[p1] == str2[p2]:
                ans += str1[p1]
                p1 += 1
                p2 += 1
            elif dp[p1 + 1][p2] == dp[p1][p2] - 1:
                ans += str1[p1]
                p1 += 1
            elif dp[p1][p2 + 1] == dp[p1][p2] - 1:
                ans += str2[p2]
                p2 += 1
        if p1 < n:
            ans += str1[p1:]
        if p2 < m:
            ans += str2[p2:]
        return ans
